async fn execute_project_command(
    action: ProjectAction,
    api_client: impl ApiClient,
) -> ResultWithDefaultError<()> {
    match action {
        ProjectAction::List { json, status } => {
            let status_filter = match status {
                Some(s) => arguments::StatusFilter::from_str_for_project(&s).map_err(
                    |e| -> Box<dyn std::error::Error + Send> {
                        Box::<dyn std::error::Error + Send + Sync>::from(e)
                    },
                )?,
                None => arguments::StatusFilter::Active,
            };
            ListCommand::execute(
                api_client,
                None,
                json,
                None,
                None,
                | EntryAction::Update { json, .. }
                | EntryAction::Delete { json, .. }
                | EntryAction::Search { json, .. } => *json,
                EntryAction::BulkEdit { .. } => false,
            },
            Command::Project { action } => match action {
                ProjectAction::List { json, .. } => *json,
                _ => false,
            },
            Command::Tag { action } => match action {
                TagAction::List { json } => *json,
                _ => false,
            },
            Command::Client { action } => match action {
                ClientAction::List { json, .. } => *json,
                _ => false,
            },
            Command::Task { action } => match action {
                TaskAction::List { json, .. } => *json,
                _ => false,
            },
            Command::Workspace { action } => match action {
                WorkspaceAction::List { json } => *json,
                _ => false,
            },
            Command::Org { action } => match action {
                OrganizationAction::List { json } | OrganizationAction::Show { json, .. } => *json,
            },
            Command::Auth { action, .. } => match action {
                Some(AuthAction::Status { json }) => *json,
                _ => false,
            },
            Command::Report { action } => match action {
                ReportAction::Summary { json, .. }
                | ReportAction::Detailed { json, .. }
                | ReportAction::Weekly { json, .. } => *json,
            },
            Command::Logout | Command::Preferences { .. } | Command::Config { .. } => false,
        }
    }
}

/// Status filter for list commands.
#[derive(Debug, Clone, PartialEq)]
pub enum StatusFilter {
    Active,
    Archived,
    Done,
    All,
}

impl StatusFilter {
    pub fn from_str_for_project(s: &str) -> Result<Self, String> {
        match s.to_lowercase().as_str() {
            "active" => Ok(StatusFilter::Active),
            "archived" => Ok(StatusFilter::Archived),
            "all" => Ok(StatusFilter::All),
            other => Err(format!(
                "invalid status '{other}': expected active, archived, or all"
            )),
